{"command":"python3 -c '
import pty, os, time, select

pid, fd = pty.fork()
if pid == 0:
    os.execv("./executable", ["executable", "-b", "-n", "1", "echo", "hello"])
else:
    end_time = time.time() + 3.5
    while time.time() < end_time:
        r, w, x = select.select([fd], [], [], 1.0)
        if fd in r:
            data = os.read(fd, 4096)
            if not data: break
            print(repr(data))
    os.kill(pid, 9)
'"}

